//! Common data types and generic structs used around FEAGI.

pub extern crate feagi_basis_proc_common;

#[cfg(feature = "alloc")]
extern crate alloc;

// Code generated by the feagi_basis_proc_common macros names everything through
// `::feagi_basis`, which this makes resolve inside of this crate too
extern crate self as feagi_basis;

/// Dependencies reached by generated code, so crates using the macros do not need them directly
#[doc(hidden)]
pub mod __private {
    pub use heapless;
    pub use serde;
}

/// Used by generated code. Emits the first block when this crate is built with its `alloc`
/// feature, otherwise the block after `else`
#[doc(hidden)]
#[cfg(feature = "alloc")]
#[macro_export]
macro_rules! __feagi_if_alloc {
    ({ $($alloc:tt)* } else { $($no_alloc:tt)* }) => {
        $($alloc)*
    };
}

/// Used by generated code. Emits the first block when this crate is built with its `alloc`
/// feature, otherwise the block after `else`
#[doc(hidden)]
#[cfg(not(feature = "alloc"))]
#[macro_export]
macro_rules! __feagi_if_alloc {
    ({ $($alloc:tt)* } else { $($no_alloc:tt)* }) => {
        $($no_alloc)*
    };
}

